import {createTrainAnnouncer} from './train-announcer.js?v=train-pa-1';
import {RADIO_STATIONS,radioStation} from './radio-stations.js?v=stations-2';
import {createAmbientAudio} from './ambient-audio.js?v=train-ride-1';
import {createRadio} from './radio.js?v=radio-ads-2';
import {createMusic,MUSIC_TRACKS} from './music.js?v=vocals-1';
import {createVehicleAudio} from './vehicle-audio.js?v=train-motion-1';
// Procedural soundscape with packaged radio spots and synthetic vocal hooks.
export function createSound({world}){
 let vehicleAudio,ambientAudio,tuningGain,tuningUntil=0,adTitle='',stationId='valley',radio,radioBus,musicTrack='auto',radioAds=true,announcer,announcerEnabled=true;
 let ctx,master,effectsBus,musicBus,music,waterFilter,splashGain,splashEnvelope=0,lastSplash=0,lastSoundTime=0,windGain,waterGain,hornGain,horn,skidGain,squeal,squealGain,muted=false,volume=.85,musicVolume=.4,musicMuted=false;
 try{const saved=JSON.parse(localStorage.getItem('wainui-audio')||'{}');if(Number.isFinite(saved.effects))volume=Math.max(0,Math.min(1,saved.effects));if(Number.isFinite(saved.music))musicVolume=Math.max(0,Math.min(1,saved.music));if(saved.track==='auto'||MUSIC_TRACKS.some(t=>t.id===saved.track))musicTrack=saved.track;stationId=radioStation(saved.station).id;radioAds=saved.radioAds!==false;announcerEnabled=saved.trainAnnouncements!==false;muted=saved.muted===true;musicMuted=saved.musicMuted===true}catch{}
 function save(){try{localStorage.setItem('wainui-audio',JSON.stringify({effects:volume,music:musicVolume,muted,musicMuted,track:musicTrack,radioAds,trainAnnouncements:announcerEnabled,station:stationId}))}catch{}}
 const $=s=>document.querySelector(s);const Audio=globalThis.AudioContext||globalThis.webkitAudioContext;
 function gain(value=0){const g=ctx.createGain();g.gain.value=value;g.connect(effectsBus);return g}
 function noise(filterType,frequency,bus=effectsBus){const buffer=ctx.createBuffer(1,ctx.sampleRate*2,ctx.sampleRate),data=buffer.getChannelData(0);let prev=0;for(let i=0;i<data.length;i++){prev=(prev+(Math.random()*2-1)*.06)/1.02;data[i]=prev}const source=ctx.createBufferSource();let peak=.001;for(const v of data)peak=Math.max(peak,Math.abs(v));for(let i=0;i<data.length;i++)data[i]*=.7/peak;source.buffer=buffer;source.loop=true;const filter=ctx.createBiquadFilter();filter.type=filterType;filter.frequency.value=frequency;const out=gain();if(bus!==effectsBus){out.disconnect();out.connect(bus)}source.connect(filter);filter.connect(out);source.start();return out}
 function start(){if(!Audio)return;try{if(!ctx){ctx=new Audio();master=ctx.createGain();master.gain.value=0;waterFilter=ctx.createBiquadFilter();waterFilter.type='lowpass';waterFilter.frequency.value=20000;effectsBus=ctx.createGain();effectsBus.gain.value=volume;effectsBus.connect(waterFilter);waterFilter.connect(master);musicBus=ctx.createGain();musicBus.gain.value=musicVolume;musicBus.connect(master);radioBus=ctx.createGain();radioBus.gain.value=.65;radioBus.connect(musicBus);radio=createRadio(ctx,radioBus,{onCaption:ad=>{adTitle=ad?.title||'';const caption=$('#radio-caption');if(caption){caption.hidden=!ad;caption.textContent=ad?`${radioStation(stationId).name.toUpperCase()} · ${ad.title} — ${ad.text}`:''}}});music=createMusic(ctx,musicBus,{onTrackEnd:time=>stationId==='valley'&&radioAds&&radio.betweenTracks(time)});music.tune(stationId);music.select(musicTrack);if(ctx.createDynamicsCompressor){const limiter=ctx.createDynamicsCompressor();limiter.threshold.value=-12;limiter.knee.value=12;limiter.ratio.value=4;limiter.attack.value=.006;limiter.release.value=.2;master.connect(limiter);limiter.connect(ctx.destination)}else master.connect(ctx.destination);announcer=createTrainAnnouncer(ctx,effectsBus,{onCaption:text=>{const caption=$('#train-announcement');if(caption){caption.hidden=!text;caption.textContent=text||''}}});vehicleAudio=createVehicleAudio(ctx,effectsBus);ambientAudio=createAmbientAudio(ctx,effectsBus,world);tuningGain=noise('bandpass',2200,musicBus);windGain=noise('lowpass',450);waterGain=noise('bandpass',1400);splashGain=noise('bandpass',850);skidGain=noise('bandpass',2300);squeal=ctx.createOscillator();squeal.type='triangle';squeal.frequency.value=820;squealGain=gain();squeal.connect(squealGain);squeal.start();horn=ctx.createOscillator();horn.type='sine';horn.frequency.value=330;hornGain=gain();horn.connect(hornGain);horn.start()}ctx.resume().catch(()=>{})}catch{}}
 function level(node,value){node?.gain.setTargetAtTime(value,ctx.currentTime,.09)}
 // Thunder: brown noise with slow random swells. Close strikes add a sharp crack and keep their highs; distant ones
 // arrive later as a soft, low rumble.
 let lastThunder=0;
 function thunder({delay,distance,power}){const near=1-Math.min(1,distance/2600),length=3.5+Math.min(4,distance/1600),rate=ctx.sampleRate,buffer=ctx.createBuffer(1,Math.floor(rate*length),rate),data=buffer.getChannelData(0);let prev=0,swell=.6,target=1,peak=.001;
  for(let i=0;i<data.length;i++){const t=i/rate;if(i%Math.floor(rate*.11)===0)target=.25+Math.random()*1.1;swell+=(target-swell)*.0005;prev=(prev+(Math.random()*2-1)*.1)/1.012;const attack=Math.min(1,t/(.015+(1-near)*.45)),decay=Math.exp(-t*4/length);data[i]=prev*swell*attack*decay+near*Math.exp(-t*7)*(Math.random()*2-1)*.35;peak=Math.max(peak,Math.abs(data[i]))}
  for(let i=0;i<data.length;i++)data[i]/=peak;const source=ctx.createBufferSource();source.buffer=buffer;const filter=ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=160+near*1900;const out=gain(Math.min(.9,power*(.3+.7*near)));source.connect(filter);filter.connect(out);source.onended=()=>{out.disconnect();filter.disconnect()};source.start(ctx.currentTime+Math.min(delay,25))}
 function update({active,position,vehicle,keys,weather,yaw=0,day=1,indoors=false}){if(!ctx)return;level(master,active&&!document.hidden&&!muted?.9:0);level(effectsBus,volume);announcer.update(active&&!document.hidden&&!muted&&volume>0&&announcerEnabled);level(musicBus,musicMuted?0:musicVolume*(announcer.active?.35:keys.h?.55:1));const musicEnabled=active&&!document.hidden&&!muted&&!musicMuted&&musicVolume>0;radio.update(musicEnabled&&radioAds);level(tuningGain,musicEnabled&&ctx.currentTime<tuningUntil?.12:0);music.update(musicEnabled&&!radio.active&&ctx.currentTime>=tuningUntil);ambientAudio.update({active:active&&!document.hidden&&!muted,position,yaw,vehicle,weather,day,indoors});const train=vehicle?.kind==='train';vehicleAudio.update(vehicle,keys,weather);level(windGain,.04+(weather?.rain||0)*.11+(weather?.storm||0)*.12);if(weather?.thunder&&weather.thunder.id!==lastThunder){lastThunder=weather.thunder.id;if(active&&!muted)thunder(weather.thunder)}waterFilter.frequency.setTargetAtTime(world.water?.underwater?550:20000,ctx.currentTime,.15);const event=world.water?.splashEvent;if(event&&event.serial!==lastSplash){lastSplash=event.serial;splashEnvelope=Math.min(.6,.12+event.power*.025)}const elapsed=Math.min(.1,Math.max(0,ctx.currentTime-lastSoundTime));lastSoundTime=ctx.currentTime;splashEnvelope*=Math.exp(-elapsed*3.5);level(splashGain,splashEnvelope);const hit=world.hydro.channel(position.x,position.z);const near=hit?1:world.hydro.nearChannel(position.x,position.z,35)?.4:0;level(waterGain,near*.2);const skid=vehicle&&!vehicle.inWater?vehicle.skid||0:0;level(skidGain,skid*.16);level(squealGain,skid*.05);squeal.frequency.setTargetAtTime(760+skid*140+Math.sin(ctx.currentTime*23)*25,ctx.currentTime,.03);level(hornGain,vehicle&&['car','train','moto'].includes(vehicle.kind)&&keys.h?(train?.3:.24):0);horn.frequency.setTargetAtTime(train?220:330,ctx.currentTime,.1)}
 function announceTrain(event){if(!event){announcer?.stop();return}if(!announcerEnabled)return;start();announcer?.update(!document.hidden&&!muted&&volume>0&&announcerEnabled);announcer?.announce(event)}
 function prepareTrainStation(name){if(announcerEnabled)announcer?.preload(name)}
 function tune(id){stationId=radioStation(id).id;musicTrack='auto';musicMuted=false;save();start();radio?.stop();music?.tune(stationId);if(ctx)tuningUntil=ctx.currentTime+.3;const station=$('#radio-station');if(station)station.value=stationId;const tracks=$('#music-track');if(tracks)tracks.value='auto';const mute=$('#music-muted');if(mute)mute.checked=false}
 function setRadioPower(enabled){musicMuted=!enabled;save();start();if(!enabled){radio?.stop();music?.update(false)}const mute=$('#music-muted');if(mute)mute.checked=musicMuted}
 function setMusicVolume(value){musicVolume=Math.max(0,Math.min(1,Number(value)||0));save();start();const slider=$('#music-volume');if(slider)slider.value=String(musicVolume)}
 const stationSelect=$('#radio-station');if(stationSelect){stationSelect.replaceChildren();for(const station of RADIO_STATIONS){const option=document.createElement('option');option.value=station.id;option.textContent=`${station.frequency} FM · ${station.name}`;stationSelect.append(option)}stationSelect.value=stationId;stationSelect.onchange=()=>tune(stationSelect.value)}
 const trackSelect=$('#music-track');if(trackSelect){trackSelect.replaceChildren();for(const track of [{id:'auto',name:'Station playlist · automatic'},...MUSIC_TRACKS]){const option=document.createElement('option');option.value=track.id;option.textContent=track.name+(track.vocals?' · Vocals':'');trackSelect.append(option)}trackSelect.value=musicTrack;trackSelect.onchange=()=>{musicTrack=trackSelect.value;save();start();radio?.stop();music?.select(musicTrack)}}
 const ads=$('#radio-ads');if(ads){ads.checked=radioAds;ads.onchange=()=>{radioAds=ads.checked;save();if(!radioAds)radio?.stop()}}
 const musicMute=$('#music-muted'),musicSlider=$('#music-volume');if(musicMute)musicMute.onchange=()=>{musicMuted=musicMute.checked;save();start()};if(musicSlider)musicSlider.oninput=()=>{musicVolume=Number(musicSlider.value);save();start()};
 const announcementControl=$('#train-announcements');if(announcementControl){announcementControl.checked=announcerEnabled;announcementControl.onchange=()=>{announcerEnabled=announcementControl.checked;save();if(!announcerEnabled)announcer?.stop()}}
 const mute=$('#sound-muted'),slider=$('#sound-volume');if(mute)mute.onchange=()=>{muted=mute.checked;save();start()};if(slider)slider.oninput=()=>{volume=Number(slider.value);save();start()};if(slider)slider.value=String(volume);if(mute)mute.checked=muted;if(musicSlider)musicSlider.value=String(musicVolume);if(musicMute)musicMute.checked=musicMuted;addEventListener('keydown',e=>{if(e.key.toLowerCase()==='h')e.preventDefault()});addEventListener('blur',()=>{if(ctx)level(master,0);radio?.stop();announcer?.stop()});document.addEventListener('visibilitychange',()=>{if(ctx&&document.hidden){level(master,0);radio?.stop();announcer?.stop()}});return{start,update,announceTrain,prepareTrainStation,tune,setRadioPower,setMusicVolume,get radioState(){return {station:stationId,power:!musicMuted,volume:musicVolume,track:ctx&&ctx.currentTime<tuningUntil?'Tuning…':music?.currentTrack.name||radioStation(stationId).tagline,ad:adTitle}}};
}
